mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Pay_Clause as conPayClause, fa.Fa_Date as faDate, fa.Fa_Code as faCode, fa.Create_Uname as createUname, mn.* from Fund_Appropriation_Dtl mn
left join Con_Contract con on mn.Con_Id = con.Con_Id left join Fund_Appropriation fa on fa.id = mn.Fa_Id where mn.Con_Id = #{params.conId}
and mn.P_Id=#{params.pId}
and fa.Te_Id = #{params.teId}
and fa.State = 7 order by fa.Create_Time desc, mn.Fad_Sort asc
